function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 300) return 'matrix needs 1 to 300 rows.';
  const n = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (n < 1 || n > 300) return 'Each row needs 1 to 300 cells.';
  if (matrix.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (matrix.some(row => row.some(cell => cell !== 0 && cell !== 1))) return 'Every cell must be 0 or 1.';
  return null;
}

