function maxEqualRowsAfterFlips(matrix) {
  const count = new Map();
  let best = 0;

  for (const row of matrix) {
    let key = '';
    for (const cell of row) {
      key += cell ^ row[0];
    }
    const total = (count.get(key) ?? 0) + 1;
    count.set(key, total);
    best = Math.max(best, total);
  }
  return best;
}

