function maxEqualRowsAfterFlips(matrix) {
  // Any useful flip set makes some row uniform; try the flip set that turns each row into all zeros.
  let best = 0;
  for (const target of matrix) {
    let uniform = 0;
    for (const row of matrix) {
      const flipped = row.map((cell, c) => cell ^ target[c]);
      if (flipped.every(v => v === flipped[0])) uniform++;
    }
    best = Math.max(best, uniform);
  }
  return best;
}

