function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const randomRow = () => Array.from({ length: n }, () => (rand() < 0.5 ? 1 : 0));
  // A few base patterns; rows copy a pattern or its complement so several rows share an answer.
  const patterns = Array.from({ length: 1 + Math.floor(rand() * (size === 'large' ? 12 : 3)) }, randomRow);
  const matrix = [];
  for (let r = 0; r < m; r++) {
    if (rand() < 0.2) { matrix.push(randomRow()); continue; }
    const base = patterns[Math.floor(rand() * patterns.length)];
    const invert = rand() < 0.5 ? 1 : 0;
    matrix.push(base.map(cell => cell ^ invert));
  }
  return [matrix];
}
